// Evaluate appointment time & medication schedules for reminders and missed events
const apptItems = $('Query Approved Appointments').all();
let medItems = [];
try {
  medItems = $('Query Active Medications').all();
} catch (_) {}

const results = [];
const seenKeys = new Set();
const now = new Date();
const todayStr = now.toISOString().substring(0, 10);

// 1. EVALUATE APPOINTMENTS
for (const item of apptItems) {
  const data = item.json;
  const apptId = data.id || data.appointmentId;
  if (!apptId) continue;

  let apptTime = null;
  if (data.dateTime && data.dateTime._seconds) {
    apptTime = new Date(data.dateTime._seconds * 1000);
  } else if (data.dateTime) {
    apptTime = new Date(data.dateTime);
  }
  if (!apptTime || isNaN(apptTime.getTime())) continue;

  const diffMinutes = (apptTime.getTime() - now.getTime()) / 60000;
  const patientId = data.patientId || '';
  const doctorId = data.doctorId || '';
  const doctorName = data.doctorName || 'Doctor';
  const patientName = data.patientName || 'Patient';
  const timeFormatted = apptTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  // CASE 1A: Upcoming in next 60 minutes -> Appointment Reminder for Patient
  if (diffMinutes > 0 && diffMinutes <= 60) {
    const eventKey = `appt_rem_${apptId}_${apptTime.toISOString().substring(0, 13)}`;
    if (!seenKeys.has(eventKey)) {
      seenKeys.add(eventKey);
      results.push({
        json: {
          category: 'appointment',
          action: 'reminder',
          eventKey,
          entityId: apptId,
          appointmentId: apptId,
          patientId,
          doctorId,
          recipientUid: patientId,
          recipientRole: 'patient',
          doctorName,
          patientName,
          title: 'Upcoming Appointment Reminder',
          message: `Your appointment with Dr. ${doctorName} is scheduled for ${timeFormatted}.`,
          telegramText: `🏥 *Continuum Health Reminder*

Your appointment with Dr. ${doctorName}
is scheduled for ${timeFormatted}.

Please be ready for your consultation.`
        }
      });
    }
  }
  // CASE 1B: Appointment time passed by 2 minutes without completion -> Missed Appointment
  else if (now.getTime() > (apptTime.getTime() + 2 * 60000)) {
    const patientEventKey = `appt_missed_p_${apptId}`;
    if (!seenKeys.has(patientEventKey)) {
      seenKeys.add(patientEventKey);
      results.push({
        json: {
          category: 'appointment',
          action: 'missed',
          eventKey: patientEventKey,
          entityId: apptId,
          appointmentId: apptId,
          patientId,
          doctorId,
          recipientUid: patientId,
          recipientRole: 'patient',
          doctorName,
          patientName,
          title: 'Appointment Missed',
          message: `You missed your scheduled appointment at ${timeFormatted}.`,
          telegramText: `Continuum Health Alert

Your appointment with Dr. ${doctorName}
scheduled for ${timeFormatted} was missed.

Please reschedule your appointment if required.`,
          doctorEscalation: !!doctorId,
          doctorTitle: 'Patient Missed Appointment',
          doctorMessage: `Patient ${patientName} missed the scheduled appointment at ${timeFormatted}.`
        }
      });
    }
  }
}

// 2. EVALUATE MEDICATIONS
for (const item of medItems) {
  const data = item.json;
  const medId = data.id || data.medicationId;
  if (!medId) continue;
  if (data.isTaken === true || data.isSkipped === true) continue;

  const targetUid = data.targetUid || data.patientId || '';
  const creatorUid = data.creatorUid || data.createdBy || '';
  const isFamily = !!(creatorUid && targetUid && creatorUid !== targetUid);
  const patientId = targetUid;
  const medName = data.name || data.medicineName || 'Prescription';
  const dosage = data.dosage || '1 dose';
  const scheduledTimeStr = data.time || data.reminderTime || 'Scheduled Time';

  // Parse time string e.g. "08:00 AM" or "14:30"
  let medDate = new Date();
  const timeMatch = scheduledTimeStr.match(/(\d+):(\d+)\s*(AM|PM)?/i);
  if (timeMatch) {
    let hours = parseInt(timeMatch[1], 10);
    const minutes = parseInt(timeMatch[2], 10);
    const meridiem = timeMatch[3] ? timeMatch[3].toUpperCase() : null;
    if (meridiem === 'PM' && hours < 12) hours += 12;
    if (meridiem === 'AM' && hours === 12) hours = 0;
    medDate.setHours(hours, minutes, 0, 0);
  }

  const diffMins = (now.getTime() - medDate.getTime()) / 60000;

  // CASE 2A: Due around now (+/- 5 mins) -> Medication Reminder for Patient
  if (Math.abs(diffMins) <= 5) {
    const eventKey = `med_rem_${medId}_${todayStr}`;
    if (!seenKeys.has(eventKey)) {
      seenKeys.add(eventKey);
      results.push({
        json: {
          category: 'medication',
          action: 'reminder',
          eventKey,
          entityId: medId,
          medicationId: medId,
          patientId,
          recipientUid: targetUid,
          recipientRole: 'patient',
          title: isFamily ? '💊 Family Medication Reminder' : 'Medication Reminder',
          message: isFamily ? `Family medication reminder for ${medName} (${dosage}) at ${scheduledTimeStr}.` : `Your medication reminder for ${medName} is due now.`,
          telegramText: isFamily
            ? `💊 Family Medication Reminder\n\nMedicine: ${medName}\nDosage: ${dosage}\nTime: ${scheduledTimeStr}`
            : `Continuum Health Medication Reminder\n\nMedicine: ${medName}\nDosage: ${dosage}\nTime: ${scheduledTimeStr}\n\nPlease take your medication as prescribed.`
        }
      });
    }
  }
  // CASE 2B: 2-minute grace period passed without taken -> Missed Medication
  else if (diffMins >= 2 && diffMins <= 360 && data.isMissed !== true) {
    const eventKey = `med_missed_${medId}_${todayStr}`;
    if (!seenKeys.has(eventKey)) {
      seenKeys.add(eventKey);
      results.push({
        json: {
          category: 'medication',
          action: 'missed',
          eventKey,
          entityId: medId,
          medicationId: medId,
          patientId,
          recipientUid: targetUid,
          recipientRole: 'patient',
          title: isFamily ? '⚠️ Missed Medication' : 'Missed Medication Alert',
          message: `We noticed your medication dose for ${medName} was not marked as taken.`,
          telegramText: isFamily
            ? `⚠️ Missed Medication\n\nMedicine: ${medName}\nDosage: ${dosage}\n\nThis medication was not marked as taken.`
            : `Continuum Health Alert\n\nYou missed your scheduled medication:\n\nMedicine: ${medName}\nDosage: ${dosage}\nScheduled: ${scheduledTimeStr}\n\nPlease follow your prescribed medication plan.`
        }
      });
    }
  }
}

return results;

// Prepare separated patient and doctor notification documents
const event = $('Evaluate Reminders & Missed Events').item.json;
const user = $('Get Recipient User').item.json || {};
const notifId = `notif_${event.eventKey}`;

return [{
  json: {
    notificationId: notifId,
    recipientUid: event.recipientUid,
    recipientRole: event.recipientRole,
    patientId: event.patientId,
    doctorId: event.doctorId || null,
    title: event.title,
    message: event.message,
    type: `${event.category}_${event.action}`,
    relatedId: event.entityId,
    appointmentId: event.appointmentId || null,
    medicationId: event.medicationId || null,
    read: false,
    isRead: false,
    telegramChatId: user.telegramChatId || null,
    deliveryStatus: user.telegramConnected ? 'sent' : 'in_app_only',
    createdAt: new Date().toISOString(),
    category: event.category,
    action: event.action,
    entityId: event.entityId,
    doctorEscalation: event.doctorEscalation || false,
    doctorTitle: event.doctorTitle || null,
    doctorMessage: event.doctorMessage || null
  }
}];
